source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_seps = [r for r, row in enumerate(grid)
                if row[0] != 0 and all(v == row[0] for v in row)]
    col_seps = [c for c in range(w)
                if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid)]
    def regions(size, seps):
        result, start = [], 0
        for s in seps:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < size:
            result.append((start, size))
        return result
    rb, cb = regions(h, row_seps), regions(w, col_seps)
    def colors_in(rr, cc):
        r0, r1 = rr; c0, c1 = cc
        return {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0}
    pairs = set()
    for i in range(len(cb)-1):
        for rr in rb:
            shared = colors_in(rr, cb[i]) & colors_in(rr, cb[i+1])
            for color in shared:
                pairs.add((i, i+1, color))
    for i, j, color in pairs:
        a0, a1 = cb[i]; b0, b1 = cb[j]
        if a1-a0 != b1-b0:
            continue
        for rr in rb:
            r0, r1 = rr
            left = [[grid[r][c] for c in range(a0,a1)] for r in range(r0,r1)]
            right = [[grid[r][c] for c in range(b0,b1)] for r in range(r0,r1)]
            has_left = any(v == color for row in left for v in row)
            has_right = any(v == color for row in right for v in row)
            if has_left == has_right:
                continue
            src, dst0 = (left, b0) if has_left else (right, a0)
            for y in range(r1-r0):
                for x in range(a1-a0):
                    if src[y][x] == color:
                        out[r0+y][dst0+(a1-a0-1-x)] = color
    return out
'''
